// Board 4 — THE NUMBERS, PER GATE: how much of each gate the spec covers, read from the generated files themselves (so it can never disagree with
// them): elements and looks specced (C1–C9), states walked and elements in the outline (structure.md), tab stops (a11y.md), relations ruled and
// passing (relations.md), and the kit-wide counts of states, motion, colours, components and tokens. Written 2026-09-30 19:45 EDT for the Session 4/5
// prep, after his ask for "the numbers of every surface, element, component, panel, state, hover, color". Run it LAST in the regenerate command.
// Writes `inventory.md`. Run: node docs/pins2/final/board4-spec/inventory.cjs
const fs = require('fs'); const path = require('path');
const D = __dirname; const rd = (f) => (fs.existsSync(path.join(D, f)) ? fs.readFileSync(path.join(D, f), 'utf8') : '');
const GATES = fs.readdirSync(D).filter((f) => /^C\d-.*\.md$/.test(f)).sort();
const count = (s, re) => (s.match(re) || []).length;
const struct = rd('structure.md'), a11y = rd('a11y.md'), rel = rd('relations.md'), states = rd('states.md');
const secOf = (s, g) => { const i = s.indexOf(`## ${g} ·`); if (i < 0) return ''; const j = s.indexOf('\n## ', i + 4); return s.slice(i, j < 0 ? undefined : j); };
const rows = GATES.map((f) => { const g = f.slice(0, 2); const c = rd(f); const st = secOf(struct, g);
  const stSections = st.split(/\n### /).slice(1); const perState = stSections.map((x) => count(x, /^\s*- /gm));
  const ay = a11y.split('\n').filter((l) => l.startsWith(`| ${g} |`)).map((l) => l.split('|').map((x) => x.trim()));
  const rl = rel.split('\n').filter((l) => l.startsWith(`| ${g} |`));
  return { g, name: (c.match(/^# .*? · (C\d · [^—\n]+)/m) || [, f])[1].trim(), elements: count(c, /^### `/gm), looks: count(c, /^#### /gm), states: stSections.length, outlineMax: perState.length ? Math.max(...perState) : 0,
    tabMax: ay.length ? Math.max(...ay.map((r) => +r[3] || 0)) : 0, a11yIssues: ay.reduce((a, r) => a + (+r[4] || 0) + (+r[5] || 0) + (+r[6] || 0) + (+r[7] || 0), 0), relations: rl.length, relOk: rl.filter((l) => /✓\s*\|\s*$/.test(l)).length }; });
if (!rows.length || rows.some((r) => !r.elements)) { console.error('inventory.cjs: a gate file has no elements — regenerate the spec first'); process.exit(1); }
const stateGroups = new Map(); for (const m of states.matchAll(/^### ([^`\n]+?) · (.+)$/gm)) { stateGroups.set(m[1], (stateGroups.get(m[1]) || 0) + 1); }
const head = (f, re) => { const m = rd(f).match(re); return m ? m[1] : '—'; };
const kit = { specced: head('README.md', /(\d+) looks specced/), signatures: head('README.md', /across (\d+) signatures/), hoverRel: head('hover-relations.md', /(\d+) rules in which/), motion: head('motion-timing.md', /(\d+) motion declarations/), timers: head('motion-timing.md', /(\d+) timers/), colourTokens: head('colours.md', /(\d+) colour tokens/), literals: head('colours.md', /(\d+) distinct literals/), mixes: head('colours.md', /(\d+) distinct `color-mix`/), components: head('components.md', /(\d+) exported components/), keyframes: String(count(rd('motion.md'), /^\*\*`/gm)), missingTokens: head('token-map.md', /(\d+) of the \d+ cus/), boardClasses: head('class-map.md', /(\d+) classes rendered/) + ' in ' + String(count(rd('class-map.md'), /^\| `/gm)) + ' prefixes' };
let md = `---\nkind: reference\nstatus: live\n---\n\n# Board 4: Collective — the numbers, per gate, generated\n\n*Generated by \`inventory.cjs\`, read from the other generated files in this folder — so a number here is only as fresh as the file it is read from; run it last in the regenerate command.*\n\n## Per gate\n\n| Gate | Elements specced | Looks | States walked | Elements in the largest state | Tab stops (most) | a11y findings | Relations ✓ / ruled |\n|---|---|---|---|---|---|---|---|\n`;
for (const r of rows) md += `| ${r.name} | ${r.elements} | ${r.looks} | ${r.states} | ${r.outlineMax} | ${r.tabMax} | ${r.a11yIssues} | ${r.relOk} / ${r.relations} |\n`;
md += `\n**Elements specced** — \`### \\\`…\\\`\` sections of the gate's value file (a signature: a tag and classes). **Looks** — its distinct resolved looks, each with every declaration and its kit \`file:line\`. **States walked** — \`structure.md\`. **a11y findings** — no name + no focus mark + unnamed controls + pointer-only, summed over its states (\`a11y.md\`).\n\n## Reachable states beyond the resting stages (\`states.md\`)\n\n| Surface | States |\n|---|---|\n${[...stateGroups].sort((a, b) => b[1] - a[1]).map(([k, n]) => `| ${k} | ${n} |`).join('\n')}\n\n## The whole kit\n\n| | |\n|---|---|\n| Looks specced / signatures | ${kit.specced} / ${kit.signatures} (\`README.md\`) |\n| Hover relations (one element's hover restyles another) | ${kit.hoverRel} (\`hover-relations.md\`) |\n| Motion declarations · component timers · @keyframes | ${kit.motion} · ${kit.timers} · ${kit.keyframes} (\`motion-timing.md\`, \`motion.md\`) |\n| Colour tokens · literals · \`color-mix\` recipes | ${kit.colourTokens} · ${kit.literals} · ${kit.mixes} (\`colours.md\`) |\n| Components exported | ${kit.components} (\`components.md\`) |\n| Board classes the portal lacks · custom properties the portal lacks | ${kit.boardClasses} · ${kit.missingTokens} (\`class-map.md\`, \`token-map.md\`) |\n`;
fs.writeFileSync(path.join(D, 'inventory.md'), md);
console.log(JSON.stringify({ out: 'inventory.md', gates: rows.length, elements: rows.reduce((a, r) => a + r.elements, 0), looks: rows.reduce((a, r) => a + r.looks, 0), states: rows.reduce((a, r) => a + r.states, 0), stateGroups: stateGroups.size }));
